      assertCustomer(url);
      return page(groups, url, "groups");
    }
    return notFound();
  };
  return {
    calls,
    messages,
    writes,
    // Fails Gmail calls with this status from now on; no argument restores delivery.
    failMail(status?: number) {
      mailFailure = status;
    },
